import {renderCommunityPassport,getCommunityEvidence} from './community-lab.js';
import {FIELD_SCHEMA,EVIDENCE_METHODS,createAssessment,setAnswer,removeAnswer,compareAssessment,rankQuestions,buildPassport,validateRecord} from './field-core.js';
import {initOffline,prepareOffline,getOfflineStatus} from './offline.js';
const invalidKeys=new Set();
const KEY='aimenergy.field-assessments.v1';let records=[],activeId=null,view='passport',context=null,apply=null,notify=null,durable=true;
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(n,d=1)=>n!==null&&n!==undefined&&Number.isFinite(Number(n))?Number(n).toLocaleString('en-US',{maximumFractionDigits:d}):'—';
const copy=v=>JSON.parse(JSON.stringify(v));
function load(){try{const raw=JSON.parse(localStorage.getItem(KEY)||'[]');if(!Array.isArray(raw))throw new Error();records=raw.filter(r=>{try{return validateRecord(r);}catch{return false;}});}catch{records=[];durable=false;}}
function save(){try{localStorage.setItem(KEY,JSON.stringify(records));durable=true;return true;}catch{durable=false;return false;}}
function active(){const id=String(context?.().site?.id);return records.find(r=>r.id===activeId&&r.siteId===id)||records.find(r=>r.siteId===id&&r.status==='draft')||records.find(r=>r.siteId===id)||null;}
function replace(r){const i=records.findIndex(x=>x.id===r.id);if(i<0)records.unshift(r);else records[i]=r;activeId=r.id;save();}
function comparison(r){return r.status==='applied'&&r.appliedComparison?r.appliedComparison:compareAssessment(r,context().profiles||{});}
function statusMarkup(){const s=getOfflineStatus();return '<div class="field-offline"><div><strong>'+(!s.online?'Offline · ':'')+(s.ready?'Offline pack ready':s.preparing?'Preparing offline pack…':'Prepare before travelling')+'</strong><p>'+esc(s.message)+'</p><small>'+(durable?'Assessments saved in this browser. Export JSON to move them; no automatic cloud sync.':'Browser storage unavailable: memory only. Export before closing.')+'</small></div><button class="btn" data-field-action="offline" '+(!s.supported||s.preparing?'disabled':'')+'>'+(s.preparing?'Preparing…':s.ready?'Refresh offline pack':'Prepare offline pack')+'</button></div>';}
export function offlineBadge(){const s=getOfflineStatus();return s.ready?(!s.online?'Offline · pack ready':'Offline pack ready'):'Offline pack not prepared';}
function updateStatus(){if($('#field-offline-status'))$('#field-offline-status').innerHTML=statusMarkup();if($('#offline-pill'))$('#offline-pill').textContent=offlineBadge();}
export function initFieldLab(options){context=options.getContext;apply=options.onApply;notify=options.notify;load();initOffline(updateStatus);return {records:records.length};}
function tabs(){return '<div class="field-tabs"><button data-field-action="tab" data-tab="passport" class="'+(view==='passport'?'active':'')+'">Evidence passport</button><button data-field-action="tab" data-tab="questions" class="'+(view==='questions'?'active':'')+'">Field questions</button><button data-field-action="tab" data-tab="history" class="'+(view==='history'?'active':'')+'">Assessment history</button></div>';}
function passportHTML(){const c=context(),rows=buildPassport(c),counts={};rows.forEach(r=>counts[r.kind]=(counts[r.kind]||0)+1);return renderCommunityPassport(c.site.id)+'<div class="field-passport-intro"><div><h3>Know the origin of every input.</h3><p>Original source records stay unchanged. Scenario responses carry their declared method and observation date.</p></div><button class="btn" data-field-action="passport-export">Download passport JSON</button></div><div class="field-tags">'+Object.entries(counts).map(([k,v])=>'<span>'+v+' '+esc(k.toLowerCase())+'</span>').join('')+'</div><div class="table-wrap"><table class="data-table field-passport"><thead><tr><th>Input</th><th>Value</th><th>Evidence type</th><th>Source / date</th></tr></thead><tbody>'+rows.map(r=>'<tr><td><strong>'+esc(r.label)+'</strong><p class="subtext">'+esc(r.detail)+'</p></td><td>'+esc(typeof r.value==='number'?fmt(r.value):r.value)+'<small>'+esc(r.unit)+'</small></td><td><span class="field-kind">'+esc(r.kind)+'</span></td><td>'+esc(r.source)+'<small>Observation date: '+esc(r.date)+'</small></td></tr>').join('')+'</tbody></table></div><div class="field-note">Source-layer dates are not recorded in the supplied processed table. Dates on assessment answers are user-declared; recording a response does not independently validate it. Reported estimates remain estimates.</div>';}
function summaryHTML(r){const c=comparison(r),answers=Object.keys(r.answers).length,sign=c.deltaKWh>=0?'+':'';return '<div class="field-comparison"><div class="eyebrow">SAME VILLAGE · VISIBLE REVISION</div><h3>'+esc(r.status==='applied'?'Applied assessment':'Draft assessment')+'</h3><div class="field-energy"><div><span>Original scenario</span><strong>'+fmt(c.before.monthlyKWh,0)+'</strong><small>kWh / month</small></div><b>→</b><div><span>With answers</span><strong>'+fmt(c.after.monthlyKWh,0)+'</strong><small>kWh / month</small></div></div><div class="field-delta">'+sign+fmt(c.deltaKWh,0)+' kWh/month scenario change</div><div class="field-mini-grid"><div><span>Household connections</span><strong>'+fmt(c.before.connections,0)+' → '+fmt(c.after.connections,0)+'</strong></div><div><span>Average-day peak</span><strong>'+fmt(c.before.peakKW)+' → '+fmt(c.after.peakKW)+' kW</strong></div></div><p>'+answers+' answer'+(answers===1?'':'s')+' recorded. Changes are scenario revisions, not measured improvements in forecast accuracy.</p><button class="btn lime" data-field-action="'+(r.status==='applied'?'restore':'apply')+'" '+(!answers||invalidKeys.size?'disabled':'')+'>'+(r.status==='applied'?'Use this saved assessment':'Apply answers to planner')+'</button><button class="btn field-dark-btn" data-field-action="report">Export assessment report</button><button class="btn field-dark-btn" data-field-action="record-export">Export assessment JSON</button><p class="field-small">Applying uses this assessment’s original inputs plus its answers. Current planner edits made after the assessment started will be replaced. Source data is retained.</p></div><div class="field-change-list"><h3>What changed?</h3>'+(c.changes.length?c.changes.map(x=>'<div><strong>'+esc(x.label)+'</strong><span>'+fmt(x.before)+' → '+fmt(x.after)+' '+esc(x.unit)+'</span><small>'+esc(x.methodLabel)+(x.observedOn?' · '+esc(x.observedOn):' · date not recorded')+'</small></div>').join(''):'<p>Answer a question to see its contribution.</p>')+'</div>';}
function questionsHTML(){const r=active();if(!r)return '<div class="empty"><h3>Turn missing information into an assessment.</h3><p>Start with the current village scenario. Five priority questions will be ranked by how much a declared test range changes monthly energy.</p><button class="btn primary" data-field-action="new" style="margin-top:18px">Start this village assessment →</button></div>';const ranked=rankQuestions(r,context().profiles||{}),disabled=r.status==='applied';return '<div class="field-session"><span>Started '+esc(new Date(r.createdAt).toLocaleString())+' · '+esc(r.siteName)+'</span><button class="btn" data-field-action="rerank">Review next priorities</button></div><div class="field-note">The first five unanswered questions are prioritized by monthly-energy sensitivity across explicit test values. Ranges are assumptions, not probability intervals or estimates of information value. Use anonymous aggregate counts; omit names and contact details.'+(disabled?' This assessment is applied and read-only. Start a follow-up to preserve its history.':'')+'</div><div class="field-assessment-grid"><div class="field-question-list">'+ranked.map((f,index)=>{const a=r.answers[f.key],methods=f.key==='householdKWhPerMonth'?Object.entries(EVIDENCE_METHODS).filter(([k])=>k!=='counted'):Object.entries(EVIDENCE_METHODS);return '<article class="field-question '+(index>=5?'field-secondary':'')+'"><div class="field-question-top"><span class="head-tag">'+(a?'Answer recorded':index<5?'Priority '+(index+1):'Additional question')+'</span><span>'+fmt(f.swingKWh,0)+' kWh/month test swing</span></div><h3>'+esc(f.question)+'</h3><p>'+esc(f.help)+'</p><div class="field-test-range">Test range: '+fmt(f.low)+'–'+fmt(f.high)+' '+esc(f.unit)+(f.swingKWh===0?' · no energy effect under the current draft':'')+'</div><div class="field-answer-row"><label>Answer <small>'+esc(f.unit)+'</small><input data-field-key="'+f.key+'" data-field-part="value" type="number" min="'+f.min+'" max="'+f.max+'" step="'+(f.integer?'1':'any')+'" placeholder="Not answered" value="'+(a?a.value:'')+'" '+(disabled?'disabled':'')+'></label><label>Evidence method<select data-field-key="'+f.key+'" data-field-part="method" '+(disabled?'disabled':'')+'>'+methods.map(([k,label])=>'<option value="'+k+'" '+((a?.method||'planned')===k?'selected':'')+'>'+label+'</option>').join('')+'</select></label></div><details><summary>Observation date & note</summary><label class="field-detail">Observation date (optional)<input type="date" max="'+new Date().toISOString().slice(0,10)+'" data-field-key="'+f.key+'" data-field-part="date" value="'+esc(a?.observedOn||'')+'" '+(disabled?'disabled':'')+'></label><label class="field-detail">Anonymous site-level note<textarea maxlength="400" data-field-key="'+f.key+'" data-field-part="note" '+(disabled?'disabled':'')+'>'+esc(a?.note||'')+'</textarea></label></details><p class="field-input-error" data-error-key="'+f.key+'" role="alert"></p><div class="field-answer-state" data-answer-state="'+f.key+'">'+(a?'Saved as '+esc(EVIDENCE_METHODS[a.method]):'Source value / current assumption: '+fmt(f.value)+' '+esc(f.unit))+'</div></article>';}).join('')+'</div><aside id="field-comparison">'+summaryHTML(r)+'</aside></div>';}
function historyHTML(){const id=String(context().site.id),rows=records.filter(r=>r.siteId===id);return rows.length?'<div class="field-history">'+rows.map(r=>{const c=comparison(r);return '<article><div><span class="head-tag">'+esc(r.status)+'</span><h3>'+esc(r.siteName)+'</h3><p>'+esc(new Date(r.createdAt).toLocaleString())+' · '+Object.keys(r.answers).length+' answers</p><strong>'+fmt(c.before.monthlyKWh,0)+' → '+fmt(c.after.monthlyKWh,0)+' kWh/month</strong></div><button class="btn" data-field-action="open" data-id="'+esc(r.id)+'">Open record →</button></article>';}).join('')+'</div>':'<div class="empty">No assessments for this village yet. Start one from Field questions.</div>';}
export function renderFieldLab(){const c=context?.();if(!c?.site)return '<div class="empty">Choose a village first.</div>';return '<section data-field-root><div class="field-heading"><div><div class="eyebrow">OBSERVE → QUESTION → REVISE</div><h2>A village assessment you can defend.</h2><p>'+esc(c.site.name)+' · inspect evidence, record answers and compare the revision.</p></div><button class="btn primary" data-field-action="new">'+(active()?'Start follow-up':'Start assessment')+'</button></div><div id="field-offline-status">'+statusMarkup()+'</div><section class="panel field-workspace">'+tabs()+(view==='passport'?passportHTML():view==='history'?historyHTML():questionsHTML())+'</section></section>';}
function render(){invalidKeys.clear();if($('[data-field-root]'))$('#view-content').innerHTML=renderFieldLab();}
function updateComparison(){const r=active();if(r&&$('#field-comparison'))$('#field-comparison').innerHTML=summaryHTML(r);updateStatus();}
function download(name,data,type){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),500);}
export function getFieldEvidence(){return {records:copy(records),active:active()?copy(active()):null,storage:durable?'browser local storage':'memory only',offline:getOfflineStatus()};}
export function assessmentReport(record){const c=comparison(record),rows=c.changes.map(x=>'<tr><td>'+esc(x.label)+'</td><td>'+fmt(x.before)+'</td><td>'+fmt(x.after)+'</td><td>'+esc(x.methodLabel)+'</td><td>'+esc(x.observedOn||'Not recorded')+'</td><td>'+esc(x.note||'')+'</td></tr>').join('');return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AimEnergy assessment — '+esc(record.siteName)+'</title><style>body{font:14px/1.7 system-ui;max-width:1050px;margin:35px auto;padding:20px;color:#173d30}h1{font-size:28px}table{border-collapse:collapse;width:100%;font-size:12px}td,th{text-align:left;padding:9px;border-bottom:1px solid #ddd;vertical-align:top}.note{padding:15px;background:#f0f5e8;border-radius:8px}button{padding:10px;margin:15px 0}@media print{button{display:none}}</style></head><body><h1>AimEnergy · Field assessment</h1><p>'+esc(record.siteName)+' · record '+esc(record.id)+' · '+esc(record.status)+'</p><p>Started '+esc(record.createdAt)+'; updated '+esc(record.updatedAt)+'</p><div class="note">Before and after are planning scenarios using the same engine and timing shapes. Their difference is not measured forecast improvement. Methods and dates are user-declared; a reported estimate is not an observed electricity reading.</div><button onclick="window.print()">Print / Save as PDF</button><h2>Monthly energy</h2><p>Original: <strong>'+fmt(c.before.monthlyKWh)+' kWh</strong>. With answers: <strong>'+fmt(c.after.monthlyKWh)+' kWh</strong>. Change: '+fmt(c.deltaKWh)+' kWh/month.</p><h2>Recorded answers</h2><table><thead><tr><th>Input</th><th>Original</th><th>Answer</th><th>Method</th><th>Observation date</th><th>Note</th></tr></thead><tbody>'+rows+'</tbody></table><h2>Original input snapshot</h2><pre>'+esc(JSON.stringify(record.baseline,null,2))+'</pre><h2>Scope</h2><p>No metered mini-grid accuracy, calibrated village interval, cost saving or equipment-sizing result was established. Business operating days are averaged over a30-day model month. Source data is retained separately from assessment answers. Records stay on this device until exported; no cloud synchronization is performed.</p></body></html>';}
async function action(name,b){if(name==='tab'){view=b.dataset.tab;render();}if(name==='new'){const r=createAssessment(context(),typeof crypto.randomUUID==='function'?crypto.randomUUID():null);replace(r);view='questions';render();}if(name==='rerank')render();if(name==='open'){activeId=b.dataset.id;view='questions';render();}if(name==='apply'){const r=active();if(!r||!Object.keys(r.answers).length||r.status==='applied'||invalidKeys.size)return;const updated={...copy(r),status:'applied',appliedAt:new Date().toISOString(),appliedComparison:compareAssessment(r,context().profiles||{})};replace(updated);apply?.(updated);notify?.('Assessment applied. Original inputs and answer history are preserved.');}if(name==='restore'){const r=active();if(r?.status==='applied'){apply?.(copy(r));notify?.('Saved assessment restored to the planner.');}}if(name==='offline'){try{await prepareOffline();notify?.('Offline pack saved. Reload once to use the prepared snapshot.');}catch(e){notify?.(e.message);}updateStatus();}if(name==='passport-export')download('AimEnergy-'+context().site.id+'-evidence-passport.json',JSON.stringify({siteId:context().site.id,siteName:context().site.name,exportedAt:new Date().toISOString(),inputs:buildPassport(context()),community:getCommunityEvidence(context().site.id),scope:'Input provenance, not an accuracy or confidence score'},null,2),'application/json');if(name==='record-export'){const r=active();if(r)download('AimEnergy-'+r.siteId+'-assessment.json',JSON.stringify(r,null,2),'application/json');}if(name==='report'){const r=active();if(r)download('AimEnergy-'+r.siteId+'-assessment-report.html',assessmentReport(r),'text/html');}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-field-action]');if(b)action(b.dataset.fieldAction,b).catch(error=>notify?.(error.message));});
function handleFieldInput(e){const key=e.target.dataset.fieldKey;if(!key)return;const r=active();if(!r||r.status==='applied')return;const card=e.target.closest('.field-question'),value=$('[data-field-root]')?card.querySelector('[data-field-part="value"]').value:'';const error=card.querySelector('[role="alert"]');try{const updated=value.trim()===''?removeAnswer(r,key):setAnswer(r,key,value,card.querySelector('[data-field-part="method"]').value,card.querySelector('[data-field-part="date"]').value,card.querySelector('[data-field-part="note"]').value);replace(updated);invalidKeys.delete(key);error.textContent='';card.querySelector('[data-answer-state]').textContent=updated.answers[key]?'Saved as '+EVIDENCE_METHODS[updated.answers[key].method]:'Answer unset; original assumption retained.';updateComparison();}catch(err){invalidKeys.add(key);error.textContent=err.message;updateComparison();}}
document.addEventListener('input',handleFieldInput);document.addEventListener('change',handleFieldInput);
